tool_use_result.content:
/* ===== CreativeHub Design System ===== */
:root {
  /* Brand Colors - OKLCH */
  --primary: oklch(55% 0.22 30);        /* #F02D00 brand red-orange */
  --primary-hover: oklch(48% 0.22 30);
  --primary-light: oklch(92% 0.04 30);
  --dark: oklch(15% 0.01 0);            /* #171717 near-black */
  --dark-700: oklch(25% 0.01 0);
  --dark-600: oklch(35% 0.01 0);
  --dark-500: oklch(45% 0.01 0);
  --white: oklch(100% 0 0);
  --gray-50: oklch(97% 0.003 0);
  --gray-100: oklch(94% 0.005 0);
  --gray-200: oklch(90% 0.005 0);
  --gray-300: oklch(82% 0.005 0);
  --gray-400: oklch(70% 0.005 0);
  --gray-500: oklch(55% 0.005 0);
  --gray-600: oklch(45% 0.005 0);
  --teal: oklch(72% 0.15 185);
  --teal-dark: oklch(60% 0.15 185);
  --green: oklch(75% 0.18 145);
  --yellow: oklch(88% 0.15 85);
  --yellow-dark: oklch(78% 0.15 85);

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-display: 'DM Sans', var(--font-sans);

  /* Spacing scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radii */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 48px oklch(0% 0 0 / 0.15);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 150ms;
  --duration-normal: 250ms;
  --duration-slow: 400ms;
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--dark);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }
ul, ol { list-style: none; }
input, select, textarea { font: inherit; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-display); font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.5rem); letter-spacing: -0.015em; }
h3 { font-size: clamp(1.2rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; }

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-lg { font-size: 1.125rem; }
.text-muted { color: var(--gray-500); }

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.section { padding: var(--space-4xl) 0; }
.section--dark { background: var(--dark); color: var(--white); }
.section--gray { background: var(--gray-50); }

.grid {
  display: grid;
  gap: var(--space-lg);
}

.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }

/* ===== Promo Banner ===== */
.promo-banner {
  background: var(--dark);
  color: var(--white);
  padding: var(--space-sm) var(--space-lg);
  text-align: center;
  font-size: 0.875rem;
  position: relative;
  z-index: 100;
}

.promo-banner__inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.promo-banner__countdown {
  display: inline-flex;
  gap: var(--space-xs);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.promo-banner__countdown span {
  background: var(--dark-700);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  min-width: 28px;
  text-align: center;
}

.promo-banner__close {
  position: absolute;
  right: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  font-size: 1.25rem;
  padding: var(--space-xs);
  transition: color var(--duration-fast);
}
.promo-banner__close:hover { color: var(--white); }

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 90;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--duration-normal);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: var(--space-xl);
}

.header__logo {
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.header__logo span { color: var(--primary); }

.header__nav { display: flex; gap: var(--space-xl); align-items: center; }
.header__nav a {
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color var(--duration-fast);
  white-space: nowrap;
}
.header__nav a:hover { color: var(--primary); }
.header__nav a.active { color: var(--primary); }

.header__search {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-full);
  padding: var(--space-sm) var(--space-md);
  flex: 1;
  max-width: 320px;
  transition: border-color var(--duration-fast);
}
.header__search:focus-within { border-color: var(--primary); }
.header__search input {
  border: none;
  background: none;
  outline: none;
  width: 100%;
  font-size: 0.875rem;
}
.header__search svg { flex-shrink: 0; color: var(--gray-400); }

.header__actions { display: flex; gap: var(--space-md); align-items: center; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  padding: 0.625rem 1.5rem;
  transition: all var(--duration-fast) var(--ease-out);
  white-space: nowrap;
}

.btn--primary { background: var(--primary); color: var(--white); }
.btn--primary:hover { background: var(--primary-hover); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn--outline { border: 2px solid var(--dark); color: var(--dark); }
.btn--outline:hover { background: var(--dark); color: var(--white); }
.btn--ghost { color: var(--dark); padding: 0.625rem 1rem; }
.btn--ghost:hover { color: var(--primary); }
.btn--dark { background: var(--dark); color: var(--white); }
.btn--dark:hover { background: var(--dark-700); }
.btn--white { background: var(--white); color: var(--dark); }
.btn--white:hover { background: var(--gray-100); }
.btn--sm { font-size: 0.8125rem; padding: 0.5rem 1rem; }
.btn--lg { font-size: 1.0625rem; padding: 0.875rem 2rem; }
.btn--icon {
  width: 40px; height: 40px; padding: 0;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
}
.btn--icon:hover { background: var(--gray-50); border-color: var(--gray-300); }

/* Mobile menu */
.header__mobile-toggle {
  display: none;
  width: 40px; height: 40px;
  align-items: center; justify-content: center;
  flex-direction: column;
  gap: 5px;
}
.header__mobile-toggle span {
  display: block; width: 22px; height: 2px;
  background: var(--dark); border-radius: 2px;
  transition: all var(--duration-normal);
}

/* ===== Hero Carousel ===== */
.hero-carousel {
  position: relative;
  overflow: hidden;
  background: var(--gray-50);
}

.hero-carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
}

.hero-carousel__slide {
  min-width: 100%;
  padding: var(--space-3xl) 0;
}

.hero-carousel__content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.hero-carousel__text { max-width: 560px; }

.hero-carousel__badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 600;
  font-size: 0.8125rem;
  padding: 0.375rem 0.875rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-lg);
}

.hero-carousel__title {
  margin-bottom: var(--space-md);
}

.hero-carousel__desc {
  color: var(--gray-500);
  font-size: 1.0625rem;
  margin-bottom: var(--space-xl);
  line-height: 1.7;
}

.hero-carousel__meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-lg);
  margin-bottom: var(--space-xl);
  font-size: 0.875rem;
}

.hero-carousel__meta-item {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}
.hero-carousel__meta-item svg { color: var(--yellow-dark); }

.hero-carousel__price {
  display: flex;
  align-items: baseline;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);
}
.hero-carousel__price-current {
  font-size: 2rem;
  font-weight: 800;
  font-family: var(--font-display);
}
.hero-carousel__price-original {
  font-size: 1.125rem;
  color: var(--gray-400);
  text-decoration: line-through;
}
.hero-carousel__price-badge {
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-full);
}

.hero-carousel__plus-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--teal-dark);
  background: oklch(95% 0.04 185);
  padding: 0.375rem 0.875rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-lg);
}

.hero-carousel__image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/3;
  background: var(--gray-200);
}

.hero-carousel__image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  color: var(--gray-400);
  background: linear-gradient(135deg, var(--gray-100), var(--gray-200));
}

.hero-carousel__nav {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-lg) 0 var(--space-xl);
}

.hero-carousel__arrow {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-fast);
  box-shadow: var(--shadow-sm);
}
.hero-carousel__arrow:hover {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.hero-carousel__dots {
  display: flex;
  gap: var(--space-sm);
}
.hero-carousel__dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--duration-normal);
  cursor: pointer;
}
.hero-carousel__dot.active {
  background: var(--primary);
  width: 28px;
  border-radius: var(--radius-full);
}

/* ===== Course Card ===== */
.course-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-normal) var(--ease-out);
  cursor: pointer;
}
.course-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.course-card__image {
  aspect-ratio: 16/10;
  background: var(--gray-200);
  position: relative;
  overflow: hidden;
}

.course-card__image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: var(--gray-400);
}

.course-card__bestseller {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--yellow);
  color: var(--dark);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
  letter-spacing: 0.03em;
}

.course-card__discount {
  position: absolute;
  top: var(--space-sm);
  right: var(--space-sm);
  background: var(--primary);
  color: var(--white);
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
}

.course-card__body {
  padding: var(--space-md);
}

.course-card__title {
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-xs);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-card__instructor {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.course-card__meta {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.course-card__rating {
  display: flex;
  align-items: center;
  gap: 3px;
  color: var(--yellow-dark);
  font-weight: 600;
}

.course-card__price {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
}
.course-card__price-current {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--dark);
}
.course-card__price-original {
  font-size: 0.8125rem;
  color: var(--gray-400);
  text-decoration: line-through;
}

.course-card__plus {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--teal-dark);
  margin-top: var(--space-sm);
}

/* ===== Course Carousel ===== */
.course-carousel {
  position: relative;
}

.course-carousel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-xl);
}

.course-carousel__track-wrapper {
  overflow: hidden;
  margin: 0 -8px;
}

.course-carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
  gap: var(--space-lg);
}

.course-carousel__track .course-card {
  min-width: calc(25% - 18px);
  flex-shrink: 0;
}

.course-carousel__arrows {
  display: flex;
  gap: var(--space-sm);
}

.carousel-arrow {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-fast);
  box-shadow: var(--shadow-sm);
}
.carousel-arrow:hover {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

/* ===== Course Grid ===== */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-lg);
}

/* ===== Value Props ===== */
.value-props__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-xl);
}

.value-prop {
  display: flex;
  gap: var(--space-md);
  padding: var(--space-lg);
}

.value-prop__icon {
  flex-shrink: 0;
  width: 48px; height: 48px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
}

.section--dark .value-prop__icon {
  background: var(--dark-700);
  color: var(--primary);
}

.value-prop__title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.value-prop__desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.6;
}
.section--dark .value-prop__desc { color: var(--gray-400); }

/* ===== Footer ===== */
.footer {
  background: var(--dark);
  color: var(--gray-400);
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--space-xl);
  margin-bottom: var(--space-3xl);
}

.footer__section-title {
  color: var(--white);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: var(--space-md);
  cursor: default;
}

.footer__links a {
  display: block;
  font-size: 0.8125rem;
  padding: 3px 0;
  transition: color var(--duration-fast);
}
.footer__links a:hover { color: var(--white); }

.footer__bottom {
  border-top: 1px solid var(--dark-700);
  padding-top: var(--space-xl);
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-md);
}

.footer__legal {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  font-size: 0.75rem;
}
.footer__legal a:hover { color: var(--white); }

.footer__apps {
  display: flex;
  gap: var(--space-sm);
}
.footer__app-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--dark-700);
  border: 1px solid var(--dark-600);
  border-radius: var(--radius-sm);
  padding: var(--space-sm) var(--space-md);
  font-size: 0.75rem;
  color: var(--white);
  transition: background var(--duration-fast);
}
.footer__app-badge:hover { background: var(--dark-600); }

/* ===== Sidebar (Courses page) ===== */
.courses-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  align-items: start;
}

.sidebar {
  position: sticky;
  top: 80px;
  max-height: calc(100vh - 100px);
  overflow-y: auto;
  padding-right: var(--space-md);
}

.sidebar__group { margin-bottom: var(--space-xl); }

.sidebar__group-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.sidebar__link {
  display: block;
  padding: var(--space-sm) var(--space-md);
  font-size: 0.875rem;
  border-radius: var(--radius-sm);
  transition: all var(--duration-fast);
  cursor: pointer;
}
.sidebar__link:hover { background: var(--gray-100); color: var(--primary); }
.sidebar__link.active {
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 600;
}

/* ===== Masonry Gallery (Projects) ===== */
.project-filters {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);
  align-items: center;
}

.filter-select {
  padding: var(--space-sm) var(--space-md);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  background: var(--white);
  color: var(--dark);
  cursor: pointer;
  appearance: none;
  background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1l4 4 4-4' stroke='%23666' stroke-width='1.5' stroke-linecap='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 12px center;
  padding-right: 32px;
  transition: border-color var(--duration-fast);
}
.filter-select:focus { outline: none; border-color: var(--primary); }

.masonry {
  columns: 4;
  column-gap: var(--space-lg);
}

.masonry__item {
  break-inside: avoid;
  margin-bottom: var(--space-lg);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-normal) var(--ease-out);
  cursor: pointer;
}
.masonry__item:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.masonry__image {
  width: 100%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 2rem;
}

.masonry__item:nth-child(odd) .masonry__image { aspect-ratio: 3/4; }
.masonry__item:nth-child(even) .masonry__image { aspect-ratio: 4/3; }
.masonry__item:nth-child(3n) .masonry__image { aspect-ratio: 1/1; }

.masonry__info {
  padding: var(--space-md);
}

.masonry__title {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.masonry__user {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.masonry__stats {
  display: flex;
  gap: var(--space-md);
  font-size: 0.75rem;
  color: var(--gray-400);
}
.masonry__stats span {
  display: flex;
  align-items: center;
  gap: 4px;
}

.masonry__winner {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--yellow);
  color: var(--dark);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
}

.masonry__item { position: relative; }

/* ===== Pricing (Plus page) ===== */
.pricing-hero {
  text-align: center;
  padding: var(--space-4xl) 0 var(--space-2xl);
  background: linear-gradient(135deg, var(--dark) 0%, oklch(22% 0.04 265) 100%);
  color: var(--white);
}

.pricing-hero__subtitle {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: var(--space-md) auto var(--space-xl);
}

.pricing-toggle {
  display: inline-flex;
  background: var(--dark-700);
  border-radius: var(--radius-full);
  padding: 4px;
  gap: 2px;
}

.pricing-toggle__btn {
  padding: var(--space-sm) var(--space-xl);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9375rem;
  transition: all var(--duration-fast);
  position: relative;
}
.pricing-toggle__btn.active {
  background: var(--primary);
  color: var(--white);
}
.pricing-toggle__btn:not(.active) { color: var(--gray-400); }
.pricing-toggle__btn:not(.active):hover { color: var(--white); }

.pricing-toggle__save {
  position: absolute;
  top: -10px;
  right: -10px;
  background: var(--green);
  color: var(--dark);
  font-size: 0.625rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--radius-full);
  white-space: nowrap;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  max-width: 480px;
  margin: var(--space-2xl) auto;
  text-align: left;
  color: var(--dark);
  box-shadow: var(--shadow-xl);
}

.pricing-card__price {
  font-size: 3rem;
  font-weight: 800;
  font-family: var(--font-display);
  line-height: 1;
  margin-bottom: var(--space-xs);
}
.pricing-card__price span { font-size: 1.125rem; font-weight: 500; color: var(--gray-500); }

.pricing-card__billed {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: var(--space-lg);
}

.pricing-card__features {
  margin-bottom: var(--space-xl);
}
.pricing-card__features li {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
}
.pricing-card__features li::before {
  content: "✓";
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card__cta {
  width: 100%;
  text-align: center;
}

.pricing-card__terms {
  font-size: 0.75rem;
  color: var(--gray-400);
  text-align: center;
  margin-top: var(--space-md);
}

/* ===== Benefits Grid ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--space-xl);
}

.benefit-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: all var(--duration-normal);
}
.benefit-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--gray-200);
}

.benefit-card__icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: var(--space-lg);
}

.benefit-card__title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.benefit-card__desc {
  font-size: 0.9375rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 720px; margin: 0 auto; }

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-item__question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-lg) 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  gap: var(--space-md);
  transition: color var(--duration-fast);
}
.faq-item__question:hover { color: var(--primary); }

.faq-item__icon {
  flex-shrink: 0;
  width: 24px; height: 24px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--duration-normal);
  font-size: 0.875rem;
}
.faq-item.open .faq-item__icon { transform: rotate(45deg); }

.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--duration-normal) var(--ease-out);
}
.faq-item.open .faq-item__answer { max-height: 500px; }

.faq-item__answer-inner {
  padding-bottom: var(--space-lg);
  font-size: 0.9375rem;
  color: var(--gray-500);
  line-height: 1.7;
}

/* ===== Login Page ===== */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--gray-50);
  padding: var(--space-xl);
}

.login-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  max-width: 440px;
  width: 100%;
  box-shadow: var(--shadow-lg);
}

.login-card__logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 800;
  text-align: center;
  margin-bottom: var(--space-2xl);
}
.login-card__logo span { color: var(--primary); }

.login-card__title {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.login-card__subtitle {
  color: var(--gray-500);
  font-size: 0.9375rem;
  margin-bottom: var(--space-xl);
}

.social-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.9375rem;
  margin-bottom: var(--space-sm);
  transition: all var(--duration-fast);
  border: 1px solid var(--gray-200);
}
.social-btn:hover { background: var(--gray-50); }
.social-btn--facebook { background: oklch(42% 0.12 265); color: var(--white); border: none; }
.social-btn--facebook:hover { background: oklch(38% 0.12 265); }
.social-btn--apple { background: var(--dark); color: var(--white); border: none; }
.social-btn--apple:hover { background: var(--dark-700); }

.login-divider {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin: var(--space-lg) 0;
  color: var(--gray-400);
  font-size: 0.8125rem;
}
.login-divider::before,
.login-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group {
  margin-bottom: var(--space-md);
}
.form-label {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}
.form-input {
  width: 100%;
  padding: 0.75rem var(--space-md);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  transition: border-color var(--duration-fast);
  outline: none;
}
.form-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-light); }

.password-field {
  position: relative;
}
.password-toggle {
  position: absolute;
  right: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  padding: var(--space-xs);
  cursor: pointer;
}
.password-toggle:hover { color: var(--dark); }

.login-card__forgot {
  display: block;
  text-align: right;
  font-size: 0.8125rem;
  color: var(--primary);
  margin-bottom: var(--space-lg);
  font-weight: 500;
}
.login-card__forgot:hover { text-decoration: underline; }

.login-card__signup {
  text-align: center;
  margin-top: var(--space-xl);
  font-size: 0.875rem;
  color: var(--gray-500);
}
.login-card__signup a {
  color: var(--primary);
  font-weight: 600;
}
.login-card__signup a:hover { text-decoration: underline; }

/* ===== Pricing Comparison ===== */
.pricing-comparison {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
  max-width: 800px;
  margin: 0 auto;
}

.pricing-col {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  border: 2px solid var(--gray-200);
  text-align: center;
  transition: all var(--duration-normal);
}
.pricing-col--recommended {
  border-color: var(--primary);
  position: relative;
}
.pricing-col--recommended::before {
  content: "Best value";
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  white-space: nowrap;
}

.pricing-col__name {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.pricing-col__price {
  font-size: 2.5rem;
  font-weight: 800;
  font-family: var(--font-display);
  margin-bottom: var(--space-xs);
}
.pricing-col__price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-500);
}

.pricing-col__billed {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-lg);
}

.pricing-col__save {
  display: inline-block;
  background: oklch(92% 0.06 145);
  color: oklch(40% 0.12 145);
  font-size: 0.8125rem;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-md);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .course-carousel__track .course-card { min-width: calc(33.333% - 16px); }
  .masonry { columns: 3; }
  .courses-layout { grid-template-columns: 220px 1fr; }
  .hero-carousel__content { gap: var(--space-xl); }
}

@media (max-width: 768px) {
  .header__nav { display: none; }
  .header__search { display: none; }
  .header__mobile-toggle { display: flex; }

  .hero-carousel__content {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .hero-carousel__image { display: none; }
  .hero-carousel__meta { justify-content: center; }
  .hero-carousel__price { justify-content: center; }

  .course-carousel__track .course-card { min-width: calc(50% - 12px); }

  .masonry { columns: 2; }

  .courses-layout { grid-template-columns: 1fr; }
  .sidebar {
    position: static;
    max-height: none;
    overflow: visible;
    padding-right: 0;
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm);
  }
  .sidebar__group { margin-bottom: var(--space-sm); width: 100%; }
  .sidebar__link {
    display: inline-block;
    padding: var(--space-xs) var(--space-md);
    border: 1px solid var(--gray-200);
    border-radius: var(--radius-full);
    font-size: 0.8125rem;
  }

  .pricing-comparison { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }

  /* Footer accordion on mobile */
  .footer__section { border-bottom: 1px solid var(--dark-700); }
  .footer__section-title {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--space-md) 0;
    cursor: pointer;
  }
  .footer__section-title::after {
    content: "+";
    font-size: 1.25rem;
    color: var(--gray-500);
    transition: transform var(--duration-normal);
  }
  .footer__section.open .footer__section-title::after { content: "−"; }
  .footer__links {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--duration-normal);
  }
  .footer__section.open .footer__links { max-height: 500px; }
}

@media (max-width: 480px) {
  .course-carousel__track .course-card { min-width: calc(80%); }
  .masonry { columns: 1; }

  .promo-banner__inner { font-size: 0.75rem; }
  .hero-carousel__slide { padding: var(--space-xl) 0; }
  .section { padding: var(--space-2xl) 0; }
}

/* ===== Utility: placeholder images ===== */
.placeholder-gradient {
  background: linear-gradient(135deg,
    oklch(85% 0.08 30),
    oklch(75% 0.12 200),
    oklch(80% 0.1 280)
  );
}
.placeholder-gradient--2 {
  background: linear-gradient(135deg,
    oklch(80% 0.1 60),
    oklch(70% 0.12 330),
    oklch(85% 0.08 180)
  );
}
.placeholder-gradient--3 {
  background: linear-gradient(135deg,
    oklch(78% 0.12 145),
    oklch(72% 0.15 200),
    oklch(82% 0.1 100)
  );
}
.placeholder-gradient--4 {
  background: linear-gradient(135deg,
    oklch(82% 0.08 280),
    oklch(75% 0.12 30),
    oklch(88% 0.06 60)
  );
}
.placeholder-gradient--5 {
  background: linear-gradient(135deg,
    oklch(78% 0.1 185),
    oklch(85% 0.08 145),
    oklch(72% 0.12 230)
  );
}

/* ===== CreativeHub Design System ===== */
:root {
  /* Brand Colors - OKLCH */
  --primary: oklch(55% 0.22 30);        /* #F02D00 brand red-orange */
  --primary-hover: oklch(48% 0.22 30);
  --primary-light: oklch(92% 0.04 30);
  --dark: oklch(15% 0.01 0);            /* #171717 near-black */
  --dark-700: oklch(25% 0.01 0);
  --dark-600: oklch(35% 0.01 0);
  --dark-500: oklch(45% 0.01 0);
  --white: oklch(100% 0 0);
  --gray-50: oklch(97% 0.003 0);
  --gray-100: oklch(94% 0.005 0);
  --gray-200: oklch(90% 0.005 0);
  --gray-300: oklch(82% 0.005 0);
  --gray-400: oklch(70% 0.005 0);
  --gray-500: oklch(55% 0.005 0);
  --gray-600: oklch(45% 0.005 0);
  --teal: oklch(72% 0.15 185);
  --teal-dark: oklch(60% 0.15 185);
  --green: oklch(75% 0.18 145);
  --yellow: oklch(88% 0.15 85);
  --yellow-dark: oklch(78% 0.15 85);

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-display: 'DM Sans', var(--font-sans);

  /* Spacing scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radii */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 48px oklch(0% 0 0 / 0.15);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 150ms;
  --duration-normal: 250ms;
  --duration-slow: 400ms;
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--dark);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }
ul, ol { list-style: none; }
input, select, textarea { font: inherit; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-display); font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.5rem); letter-spacing: -0.015em; }
h3 { font-size: clamp(1.2rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; }

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-lg { font-size: 1.125rem; }
.text-muted { color: var(--gray-500); }

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.section { padding: var(--space-4xl) 0; }
.section--dark { background: var(--dark); color: var(--white); }
.section--gray { background: var(--gray-50); }

.grid {
  display: grid;
  gap: var(--space-lg);
}

.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }

/* ===== Promo Banner ===== */
.promo-banner {
  background: var(--dark);
  color: var(--white);
  padding: var(--space-sm) var(--space-lg);
  text-align: center;
  font-size: 0.875rem;
  position: relative;
  z-index: 100;
}

.promo-banner__inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.promo-banner__countdown {
  display: inline-flex;
  gap: var(--space-xs);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.promo-banner__countdown span {
  background: var(--dark-700);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  min-width: 28px;
  text-align: center;
}

.promo-banner__close {
  position: absolute;
  right: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  font-size: 1.25rem;
  padding: var(--space-xs);
  transition: color var(--duration-fast);
}
.promo-banner__close:hover { color: var(--white); }

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 90;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--duration-normal);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: var(--space-xl);
}

.header__logo {
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.header__logo span { color: var(--primary); }

.header__nav { display: flex; gap: var(--space-xl); align-items: center; }
.header__nav a {
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color var(--duration-fast);
  white-space: nowrap;
}
.header__nav a:hover { color: var(--primary); }
.header__nav a.active { color: var(--primary); }

.header__search {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-full);
  padding: var(--space-sm) var(--space-md);
  flex: 1;
  max-width: 320px;
  transition: border-color var(--duration-fast);
}
.header__search:focus-within { border-color: var(--primary); }
.header__search input {
  border: none;
  background: none;
  outline: none;
  width: 100%;
  font-size: 0.875rem;
}
.header__search svg { flex-shrink: 0; color: var(--gray-400); }

.header__actions { display: flex; gap: var(--space-md); align-items: center; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  padding: 0.625rem 1.5rem;
  transition: all var(--duration-fast) var(--ease-out);
  white-space: nowrap;
}

.btn--primary { background: var(--primary); color: var(--white); }
.btn--primary:hover { background: var(--primary-hover); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn--outline { border: 2px solid var(--dark); color: var(--dark); }
.btn--outline:hover { background: var(--dark); color: var(--white); }
.btn--ghost { color: var(--dark); padding: 0.625rem 1rem; }
.btn--ghost:hover { color: var(--primary); }
.btn--dark { background: var(--dark); color: var(--white); }
.btn--dark:hover { background: var(--dark-700); }
.btn--white { background: var(--white); color: var(--dark); }
.btn--white:hover { background: var(--gray-100); }
.btn--sm { font-size: 0.8125rem; padding: 0.5rem 1rem; }
.btn--lg { font-size: 1.0625rem; padding: 0.875rem 2rem; }
.btn--icon {
  width: 40px; height: 40px; padding: 0;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
}
.btn--icon:hover { background: var(--gray-50); border-color: var(--gray-300); }

/* Mobile menu */
.header__mobile-toggle {
  display: none;
  width: 40px; height: 40px;
  align-items: center; justify-content: center;
  flex-direction: column;
  gap: 5px;
}
.header__mobile-toggle span {
  display: block; width: 22px; height: 2px;
  background: var(--dark); border-radius: 2px;
  transition: all var(--duration-normal);
}

/* ===== Hero Carousel ===== */
.hero-carousel {
  position: relative;
  overflow: hidden;
  background: var(--gray-50);
}

.hero-carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
}

.hero-carousel__slide {
  min-width: 100%;
  padding: var(--space-3xl) 0;
}

.hero-carousel__content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.hero-carousel__text { max-width: 560px; }

.hero-carousel__badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 600;
  font-size: 0.8125rem;
  padding: 0.375rem 0.875rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-lg);
}

.hero-carousel__title {
  margin-bottom: var(--space-md);
}

.hero-carousel__desc {
  color: var(--gray-500);
  font-size: 1.0625rem;
  margin-bottom: var(--space-xl);
  line-height: 1.7;
}

.hero-carousel__meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-lg);
  margin-bottom: var(--space-xl);
  font-size: 0.875rem;
}

.hero-carousel__meta-item {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}
.hero-carousel__meta-item svg { color: var(--yellow-dark); }

.hero-carousel__price {
  display: flex;
  align-items: baseline;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);
}
.hero-carousel__price-current {
  font-size: 2rem;
  font-weight: 800;
  font-family: var(--font-display);
}
.hero-carousel__price-original {
  font-size: 1.125rem;
  color: var(--gray-400);
  text-decoration: line-through;
}
.hero-carousel__price-badge {
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-full);
}

.hero-carousel__plus-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--teal-dark);
  background: oklch(95% 0.04 185);
  padding: 0.375rem 0.875rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-lg);
}

.hero-carousel__image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/3;
  background: var(--gray-200);
}

.hero-carousel__image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  color: var(--gray-400);
  background: linear-gradient(135deg, var(--gray-100), var(--gray-200));
}

.hero-carousel__nav {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-lg) 0 var(--space-xl);
}

.hero-carousel__arrow {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-fast);
  box-shadow: var(--shadow-sm);
}
.hero-carousel__arrow:hover {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.hero-carousel__dots {
  display: flex;
  gap: var(--space-sm);
}
.hero-carousel__dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--duration-normal);
  cursor: pointer;
}
.hero-carousel__dot.active {
  background: var(--primary);
  width: 28px;
  border-radius: var(--radius-full);
}

/* ===== Course Card ===== */
.course-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-normal) var(--ease-out);
  cursor: pointer;
}
.course-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.course-card__image {
  aspect-ratio: 16/10;
  background: var(--gray-200);
  position: relative;
  overflow: hidden;
}

.course-card__image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: var(--gray-400);
}

.course-card__bestseller {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--yellow);
  color: var(--dark);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
  letter-spacing: 0.03em;
}

.course-card__discount {
  position: absolute;
  top: var(--space-sm);
  right: var(--space-sm);
  background: var(--primary);
  color: var(--white);
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
}

.course-card__body {
  padding: var(--space-md);
}

.course-card__title {
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-xs);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-card__instructor {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.course-card__meta {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.course-card__rating {
  display: flex;
  align-items: center;
  gap: 3px;
  color: var(--yellow-dark);
  font-weight: 600;
}

.course-card__price {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
}
.course-card__price-current {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--dark);
}
.course-card__price-original {
  font-size: 0.8125rem;
  color: var(--gray-400);
  text-decoration: line-through;
}

.course-card__plus {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--teal-dark);
  margin-top: var(--space-sm);
}

/* ===== Course Carousel ===== */
.course-carousel {
  position: relative;
}

.course-carousel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-xl);
}

.course-carousel__track-wrapper {
  overflow: hidden;
  margin: 0 -8px;
}

.course-carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
  gap: var(--space-lg);
}

.course-carousel__track .course-card {
  min-width: calc(25% - 18px);
  flex-shrink: 0;
}

.course-carousel__arrows {
  display: flex;
  gap: var(--space-sm);
}

.carousel-arrow {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-fast);
  box-shadow: var(--shadow-sm);
}
.carousel-arrow:hover {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

/* ===== Course Grid ===== */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-lg);
}

/* ===== Value Props ===== */
.value-props__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-xl);
}

.value-prop {
  display: flex;
  gap: var(--space-md);
  padding: var(--space-lg);
}

.value-prop__icon {
  flex-shrink: 0;
  width: 48px; height: 48px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
}

.section--dark .value-prop__icon {
  background: var(--dark-700);
  color: var(--primary);
}

.value-prop__title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.value-prop__desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.6;
}
.section--dark .value-prop__desc { color: var(--gray-400); }

/* ===== Footer ===== */
.footer {
  background: var(--dark);
  color: var(--gray-400);
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--space-xl);
  margin-bottom: var(--space-3xl);
}

.footer__section-title {
  color: var(--white);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: var(--space-md);
  cursor: default;
}

.footer__links a {
  display: block;
  font-size: 0.8125rem;
  padding: 3px 0;
  transition: color var(--duration-fast);
}
.footer__links a:hover { color: var(--white); }

.footer__bottom {
  border-top: 1px solid var(--dark-700);
  padding-top: var(--space-xl);
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-md);
}

.footer__legal {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  font-size: 0.75rem;
}
.footer__legal a:hover { color: var(--white); }

.footer__apps {
  display: flex;
  gap: var(--space-sm);
}
.footer__app-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--dark-700);
  border: 1px solid var(--dark-600);
  border-radius: var(--radius-sm);
  padding: var(--space-sm) var(--space-md);
  font-size: 0.75rem;
  color: var(--white);
  transition: background var(--duration-fast);
}
.footer__app-badge:hover { background: var(--dark-600); }

/* ===== Sidebar (Courses page) ===== */
.courses-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  align-items: start;
}

.sidebar {
  position: sticky;
  top: 80px;
  max-height: calc(100vh - 100px);
  overflow-y: auto;
  padding-right: var(--space-md);
}

.sidebar__group { margin-bottom: var(--space-xl); }

.sidebar__group-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.sidebar__link {
  display: block;
  padding: var(--space-sm) var(--space-md);
  font-size: 0.875rem;
  border-radius: var(--radius-sm);
  transition: all var(--duration-fast);
  cursor: pointer;
}
.sidebar__link:hover { background: var(--gray-100); color: var(--primary); }
.sidebar__link.active {
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 600;
}

/* ===== Masonry Gallery (Projects) ===== */
.project-filters {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);
  align-items: center;
}

.filter-select {
  padding: var(--space-sm) var(--space-md);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  background: var(--white);
  color: var(--dark);
  cursor: pointer;
  appearance: none;
  background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1l4 4 4-4' stroke='%23666' stroke-width='1.5' stroke-linecap='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 12px center;
  padding-right: 32px;
  transition: border-color var(--duration-fast);
}
.filter-select:focus { outline: none; border-color: var(--primary); }

.masonry {
  columns: 4;
  column-gap: var(--space-lg);
}

.masonry__item {
  break-inside: avoid;
  margin-bottom: var(--space-lg);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-normal) var(--ease-out);
  cursor: pointer;
}
.masonry__item:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.masonry__image {
  width: 100%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 2rem;
}

.masonry__item:nth-child(odd) .masonry__image { aspect-ratio: 3/4; }
.masonry__item:nth-child(even) .masonry__image { aspect-ratio: 4/3; }
.masonry__item:nth-child(3n) .masonry__image { aspect-ratio: 1/1; }

.masonry__info {
  padding: var(--space-md);
}

.masonry__title {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.masonry__user {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.masonry__stats {
  display: flex;
  gap: var(--space-md);
  font-size: 0.75rem;
  color: var(--gray-400);
}
.masonry__stats span {
  display: flex;
  align-items: center;
  gap: 4px;
}

.masonry__winner {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--yellow);
  color: var(--dark);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
}

.masonry__item { position: relative; }

/* ===== Pricing (Plus page) ===== */
.pricing-hero {
  text-align: center;
  padding: var(--space-4xl) 0 var(--space-2xl);
  background: linear-gradient(135deg, var(--dark) 0%, oklch(22% 0.04 265) 100%);
  color: var(--white);
}

.pricing-hero__subtitle {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: var(--space-md) auto var(--space-xl);
}

.pricing-toggle {
  display: inline-flex;
  background: var(--dark-700);
  border-radius: var(--radius-full);
  padding: 4px;
  gap: 2px;
}

.pricing-toggle__btn {
  padding: var(--space-sm) var(--space-xl);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9375rem;
  transition: all var(--duration-fast);
  position: relative;
}
.pricing-toggle__btn.active {
  background: var(--primary);
  color: var(--white);
}
.pricing-toggle__btn:not(.active) { color: var(--gray-400); }
.pricing-toggle__btn:not(.active):hover { color: var(--white); }

.pricing-toggle__save {
  position: absolute;
  top: -10px;
  right: -10px;
  background: var(--green);
  color: var(--dark);
  font-size: 0.625rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--radius-full);
  white-space: nowrap;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  max-width: 480px;
  margin: var(--space-2xl) auto;
  text-align: left;
  color: var(--dark);
  box-shadow: var(--shadow-xl);
}

.pricing-card__price {
  font-size: 3rem;
  font-weight: 800;
  font-family: var(--font-display);
  line-height: 1;
  margin-bottom: var(--space-xs);
}
.pricing-card__price span { font-size: 1.125rem; font-weight: 500; color: var(--gray-500); }

.pricing-card__billed {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: var(--space-lg);
}

.pricing-card__features {
  margin-bottom: var(--space-xl);
}
.pricing-card__features li {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
}
.pricing-card__features li::before {
  content: "✓";
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card__cta {
  width: 100%;
  text-align: center;
}

.pricing-card__terms {
  font-size: 0.75rem;
  color: var(--gray-400);
  text-align: center;
  margin-top: var(--space-md);
}

/* ===== Benefits Grid ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--space-xl);
}

.benefit-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: all var(--duration-normal);
}
.benefit-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--gray-200);
}

.benefit-card__icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: var(--space-lg);
}

.benefit-card__title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.benefit-card__desc {
  font-size: 0.9375rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 720px; margin: 0 auto; }

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-item__question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-lg) 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  gap: var(--space-md);
  transition: color var(--duration-fast);
}
.faq-item__question:hover { color: var(--primary); }

.faq-item__icon {
  flex-shrink: 0;
  width: 24px; height: 24px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--duration-normal);
  font-size: 0.875rem;
}
.faq-item.open .faq-item__icon { transform: rotate(45deg); }

.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--duration-normal) var(--ease-out);
}
.faq-item.open .faq-item__answer { max-height: 500px; }

.faq-item__answer-inner {
  padding-bottom: var(--space-lg);
  font-size: 0.9375rem;
  color: var(--gray-500);
  line-height: 1.7;
}

/* ===== Login Page ===== */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--gray-50);
  padding: var(--space-xl);
}

.login-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  max-width: 440px;
  width: 100%;
  box-shadow: var(--shadow-lg);
}

.login-card__logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 800;
  text-align: center;
  margin-bottom: var(--space-2xl);
}
.login-card__logo span { color: var(--primary); }

.login-card__title {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.login-card__subtitle {
  color: var(--gray-500);
  font-size: 0.9375rem;
  margin-bottom: var(--space-xl);
}

.social-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.9375rem;
  margin-bottom: var(--space-sm);
  transition: all var(--duration-fast);
  border: 1px solid var(--gray-200);
}
.social-btn:hover { background: var(--gray-50); }
.social-btn--facebook { background: oklch(42% 0.12 265); color: var(--white); border: none; }
.social-btn--facebook:hover { background: oklch(38% 0.12 265); }
.social-btn--apple { background: var(--dark); color: var(--white); border: none; }
.social-btn--apple:hover { background: var(--dark-700); }

.login-divider {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin: var(--space-lg) 0;
  color: var(--gray-400);
  font-size: 0.8125rem;
}
.login-divider::before,
.login-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group {
  margin-bottom: var(--space-md);
}
.form-label {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}
.form-input {
  width: 100%;
  padding: 0.75rem var(--space-md);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  transition: border-color var(--duration-fast);
  outline: none;
}
.form-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-light); }

.password-field {
  position: relative;
}
.password-toggle {
  position: absolute;
  right: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  padding: var(--space-xs);
  cursor: pointer;
}
.password-toggle:hover { color: var(--dark); }

.login-card__forgot {
  display: block;
  text-align: right;
  font-size: 0.8125rem;
  color: var(--primary);
  margin-bottom: var(--space-lg);
  font-weight: 500;
}
.login-card__forgot:hover { text-decoration: underline; }

.login-card__signup {
  text-align: center;
  margin-top: var(--space-xl);
  font-size: 0.875rem;
  color: var(--gray-500);
}
.login-card__signup a {
  color: var(--primary);
  font-weight: 600;
}
.login-card__signup a:hover { text-decoration: underline; }

/* ===== Pricing Comparison ===== */
.pricing-comparison {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
  max-width: 800px;
  margin: 0 auto;
}

.pricing-col {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  border: 2px solid var(--gray-200);
  text-align: center;
  transition: all var(--duration-normal);
}
.pricing-col--recommended {
  border-color: var(--primary);
  position: relative;
}
.pricing-col--recommended::before {
  content: "Best value";
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  white-space: nowrap;
}

.pricing-col__name {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.pricing-col__price {
  font-size: 2.5rem;
  font-weight: 800;
  font-family: var(--font-display);
  margin-bottom: var(--space-xs);
}
.pricing-col__price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-500);
}

.pricing-col__billed {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-lg);
}

.pricing-col__save {
  display: inline-block;
  background: oklch(92% 0.06 145);
  color: oklch(40% 0.12 145);
  font-size: 0.8125rem;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-md);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .course-carousel__track .course-card { min-width: calc(33.333% - 16px); }
  .masonry { columns: 3; }
  .courses-layout { grid-template-columns: 220px 1fr; }
  .hero-carousel__content { gap: var(--space-xl); }
}

@media (max-width: 768px) {
  .header__nav { display: none; }
  .header__search { display: none; }
  .header__mobile-toggle { display: flex; }

  .hero-carousel__content {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .hero-carousel__image { display: none; }
  .hero-carousel__meta { justify-content: center; }
  .hero-carousel__price { justify-content: center; }

  .course-carousel__track .course-card { min-width: calc(50% - 12px); }

  .masonry { columns: 2; }

  .courses-layout { grid-template-columns: 1fr; }
  .sidebar {
    position: static;
    max-height: none;
    overflow: visible;
    padding-right: 0;
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm);
  }
  .sidebar__group { margin-bottom: var(--space-sm); width: 100%; }
  .sidebar__link {
    display: inline-block;
    padding: var(--space-xs) var(--space-md);
    border: 1px solid var(--gray-200);
    border-radius: var(--radius-full);
    font-size: 0.8125rem;
  }

  .pricing-comparison { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }

  /* Footer accordion on mobile */
  .footer__section { border-bottom: 1px solid var(--dark-700); }
  .footer__section-title {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--space-md) 0;
    cursor: pointer;
  }
  .footer__section-title::after {
    content: "+";
    font-size: 1.25rem;
    color: var(--gray-500);
    transition: transform var(--duration-normal);
  }
  .footer__section.open .footer__section-title::after { content: "−"; }
  .footer__links {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--duration-normal);
  }
  .footer__section.open .footer__links { max-height: 500px; }
}

@media (max-width: 480px) {
  .course-carousel__track .course-card { min-width: calc(80%); }
  .masonry { columns: 1; }

  .promo-banner__inner { font-size: 0.75rem; }
  .hero-carousel__slide { padding: var(--space-xl) 0; }
  .section { padding: var(--space-2xl) 0; }
}

/* ===== Utility: placeholder images ===== */
.placeholder-gradient {
  background: linear-gradient(135deg,
    oklch(85% 0.08 30),
    oklch(75% 0.12 200),
    oklch(80% 0.1 280)
  );
}
.placeholder-gradient--2 {
  background: linear-gradient(135deg,
    oklch(80% 0.1 60),
    oklch(70% 0.12 330),
    oklch(85% 0.08 180)
  );
}
.placeholder-gradient--3 {
  background: linear-gradient(135deg,
    oklch(78% 0.12 145),
    oklch(72% 0.15 200),
    oklch(82% 0.1 100)
  );
}
.placeholder-gradient--4 {
  background: linear-gradient(135deg,
    oklch(82% 0.08 280),
    oklch(75% 0.12 30),
    oklch(88% 0.06 60)
  );
}
.placeholder-gradient--5 {
  background: linear-gradient(135deg,
    oklch(78% 0.1 185),
    oklch(85% 0.08 145),
    oklch(72% 0.12 230)
  );
}

raw_arguments.content:
/* ===== CreativeHub Design System ===== */
:root {
  /* Brand Colors - OKLCH */
  --primary: oklch(55% 0.22 30);        /* #F02D00 brand red-orange */
  --primary-hover: oklch(48% 0.22 30);
  --primary-light: oklch(92% 0.04 30);
  --dark: oklch(15% 0.01 0);            /* #171717 near-black */
  --dark-700: oklch(25% 0.01 0);
  --dark-600: oklch(35% 0.01 0);
  --dark-500: oklch(45% 0.01 0);
  --white: oklch(100% 0 0);
  --gray-50: oklch(97% 0.003 0);
  --gray-100: oklch(94% 0.005 0);
  --gray-200: oklch(90% 0.005 0);
  --gray-300: oklch(82% 0.005 0);
  --gray-400: oklch(70% 0.005 0);
  --gray-500: oklch(55% 0.005 0);
  --gray-600: oklch(45% 0.005 0);
  --teal: oklch(72% 0.15 185);
  --teal-dark: oklch(60% 0.15 185);
  --green: oklch(75% 0.18 145);
  --yellow: oklch(88% 0.15 85);
  --yellow-dark: oklch(78% 0.15 85);

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-display: 'DM Sans', var(--font-sans);

  /* Spacing scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radii */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 48px oklch(0% 0 0 / 0.15);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 150ms;
  --duration-normal: 250ms;
  --duration-slow: 400ms;
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--dark);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }
ul, ol { list-style: none; }
input, select, textarea { font: inherit; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-display); font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.5rem); letter-spacing: -0.015em; }
h3 { font-size: clamp(1.2rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; }

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-lg { font-size: 1.125rem; }
.text-muted { color: var(--gray-500); }

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.section { padding: var(--space-4xl) 0; }
.section--dark { background: var(--dark); color: var(--white); }
.section--gray { background: var(--gray-50); }

.grid {
  display: grid;
  gap: var(--space-lg);
}

.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }

/* ===== Promo Banner ===== */
.promo-banner {
  background: var(--dark);
  color: var(--white);
  padding: var(--space-sm) var(--space-lg);
  text-align: center;
  font-size: 0.875rem;
  position: relative;
  z-index: 100;
}

.promo-banner__inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.promo-banner__countdown {
  display: inline-flex;
  gap: var(--space-xs);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.promo-banner__countdown span {
  background: var(--dark-700);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  min-width: 28px;
  text-align: center;
}

.promo-banner__close {
  position: absolute;
  right: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  font-size: 1.25rem;
  padding: var(--space-xs);
  transition: color var(--duration-fast);
}
.promo-banner__close:hover { color: var(--white); }

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 90;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--duration-normal);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: var(--space-xl);
}

.header__logo {
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.header__logo span { color: var(--primary); }

.header__nav { display: flex; gap: var(--space-xl); align-items: center; }
.header__nav a {
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color var(--duration-fast);
  white-space: nowrap;
}
.header__nav a:hover { color: var(--primary); }
.header__nav a.active { color: var(--primary); }

.header__search {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-full);
  padding: var(--space-sm) var(--space-md);
  flex: 1;
  max-width: 320px;
  transition: border-color var(--duration-fast);
}
.header__search:focus-within { border-color: var(--primary); }
.header__search input {
  border: none;
  background: none;
  outline: none;
  width: 100%;
  font-size: 0.875rem;
}
.header__search svg { flex-shrink: 0; color: var(--gray-400); }

.header__actions { display: flex; gap: var(--space-md); align-items: center; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  padding: 0.625rem 1.5rem;
  transition: all var(--duration-fast) var(--ease-out);
  white-space: nowrap;
}

.btn--primary { background: var(--primary); color: var(--white); }
.btn--primary:hover { background: var(--primary-hover); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn--outline { border: 2px solid var(--dark); color: var(--dark); }
.btn--outline:hover { background: var(--dark); color: var(--white); }
.btn--ghost { color: var(--dark); padding: 0.625rem 1rem; }
.btn--ghost:hover { color: var(--primary); }
.btn--dark { background: var(--dark); color: var(--white); }
.btn--dark:hover { background: var(--dark-700); }
.btn--white { background: var(--white); color: var(--dark); }
.btn--white:hover { background: var(--gray-100); }
.btn--sm { font-size: 0.8125rem; padding: 0.5rem 1rem; }
.btn--lg { font-size: 1.0625rem; padding: 0.875rem 2rem; }
.btn--icon {
  width: 40px; height: 40px; padding: 0;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
}
.btn--icon:hover { background: var(--gray-50); border-color: var(--gray-300); }

/* Mobile menu */
.header__mobile-toggle {
  display: none;
  width: 40px; height: 40px;
  align-items: center; justify-content: center;
  flex-direction: column;
  gap: 5px;
}
.header__mobile-toggle span {
  display: block; width: 22px; height: 2px;
  background: var(--dark); border-radius: 2px;
  transition: all var(--duration-normal);
}

/* ===== Hero Carousel ===== */
.hero-carousel {
  position: relative;
  overflow: hidden;
  background: var(--gray-50);
}

.hero-carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
}

.hero-carousel__slide {
  min-width: 100%;
  padding: var(--space-3xl) 0;
}

.hero-carousel__content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.hero-carousel__text { max-width: 560px; }

.hero-carousel__badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 600;
  font-size: 0.8125rem;
  padding: 0.375rem 0.875rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-lg);
}

.hero-carousel__title {
  margin-bottom: var(--space-md);
}

.hero-carousel__desc {
  color: var(--gray-500);
  font-size: 1.0625rem;
  margin-bottom: var(--space-xl);
  line-height: 1.7;
}

.hero-carousel__meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-lg);
  margin-bottom: var(--space-xl);
  font-size: 0.875rem;
}

.hero-carousel__meta-item {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}
.hero-carousel__meta-item svg { color: var(--yellow-dark); }

.hero-carousel__price {
  display: flex;
  align-items: baseline;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);
}
.hero-carousel__price-current {
  font-size: 2rem;
  font-weight: 800;
  font-family: var(--font-display);
}
.hero-carousel__price-original {
  font-size: 1.125rem;
  color: var(--gray-400);
  text-decoration: line-through;
}
.hero-carousel__price-badge {
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-full);
}

.hero-carousel__plus-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--teal-dark);
  background: oklch(95% 0.04 185);
  padding: 0.375rem 0.875rem;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-lg);
}

.hero-carousel__image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/3;
  background: var(--gray-200);
}

.hero-carousel__image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  color: var(--gray-400);
  background: linear-gradient(135deg, var(--gray-100), var(--gray-200));
}

.hero-carousel__nav {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-lg) 0 var(--space-xl);
}

.hero-carousel__arrow {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-fast);
  box-shadow: var(--shadow-sm);
}
.hero-carousel__arrow:hover {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.hero-carousel__dots {
  display: flex;
  gap: var(--space-sm);
}
.hero-carousel__dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--duration-normal);
  cursor: pointer;
}
.hero-carousel__dot.active {
  background: var(--primary);
  width: 28px;
  border-radius: var(--radius-full);
}

/* ===== Course Card ===== */
.course-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-normal) var(--ease-out);
  cursor: pointer;
}
.course-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.course-card__image {
  aspect-ratio: 16/10;
  background: var(--gray-200);
  position: relative;
  overflow: hidden;
}

.course-card__image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: var(--gray-400);
}

.course-card__bestseller {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--yellow);
  color: var(--dark);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
  letter-spacing: 0.03em;
}

.course-card__discount {
  position: absolute;
  top: var(--space-sm);
  right: var(--space-sm);
  background: var(--primary);
  color: var(--white);
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
}

.course-card__body {
  padding: var(--space-md);
}

.course-card__title {
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-xs);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-card__instructor {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.course-card__meta {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.course-card__rating {
  display: flex;
  align-items: center;
  gap: 3px;
  color: var(--yellow-dark);
  font-weight: 600;
}

.course-card__price {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
}
.course-card__price-current {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--dark);
}
.course-card__price-original {
  font-size: 0.8125rem;
  color: var(--gray-400);
  text-decoration: line-through;
}

.course-card__plus {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--teal-dark);
  margin-top: var(--space-sm);
}

/* ===== Course Carousel ===== */
.course-carousel {
  position: relative;
}

.course-carousel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-xl);
}

.course-carousel__track-wrapper {
  overflow: hidden;
  margin: 0 -8px;
}

.course-carousel__track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
  gap: var(--space-lg);
}

.course-carousel__track .course-card {
  min-width: calc(25% - 18px);
  flex-shrink: 0;
}

.course-carousel__arrows {
  display: flex;
  gap: var(--space-sm);
}

.carousel-arrow {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-fast);
  box-shadow: var(--shadow-sm);
}
.carousel-arrow:hover {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

/* ===== Course Grid ===== */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-lg);
}

/* ===== Value Props ===== */
.value-props__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-xl);
}

.value-prop {
  display: flex;
  gap: var(--space-md);
  padding: var(--space-lg);
}

.value-prop__icon {
  flex-shrink: 0;
  width: 48px; height: 48px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
}

.section--dark .value-prop__icon {
  background: var(--dark-700);
  color: var(--primary);
}

.value-prop__title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.value-prop__desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.6;
}
.section--dark .value-prop__desc { color: var(--gray-400); }

/* ===== Footer ===== */
.footer {
  background: var(--dark);
  color: var(--gray-400);
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--space-xl);
  margin-bottom: var(--space-3xl);
}

.footer__section-title {
  color: var(--white);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: var(--space-md);
  cursor: default;
}

.footer__links a {
  display: block;
  font-size: 0.8125rem;
  padding: 3px 0;
  transition: color var(--duration-fast);
}
.footer__links a:hover { color: var(--white); }

.footer__bottom {
  border-top: 1px solid var(--dark-700);
  padding-top: var(--space-xl);
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-md);
}

.footer__legal {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  font-size: 0.75rem;
}
.footer__legal a:hover { color: var(--white); }

.footer__apps {
  display: flex;
  gap: var(--space-sm);
}
.footer__app-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--dark-700);
  border: 1px solid var(--dark-600);
  border-radius: var(--radius-sm);
  padding: var(--space-sm) var(--space-md);
  font-size: 0.75rem;
  color: var(--white);
  transition: background var(--duration-fast);
}
.footer__app-badge:hover { background: var(--dark-600); }

/* ===== Sidebar (Courses page) ===== */
.courses-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  align-items: start;
}

.sidebar {
  position: sticky;
  top: 80px;
  max-height: calc(100vh - 100px);
  overflow-y: auto;
  padding-right: var(--space-md);
}

.sidebar__group { margin-bottom: var(--space-xl); }

.sidebar__group-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.sidebar__link {
  display: block;
  padding: var(--space-sm) var(--space-md);
  font-size: 0.875rem;
  border-radius: var(--radius-sm);
  transition: all var(--duration-fast);
  cursor: pointer;
}
.sidebar__link:hover { background: var(--gray-100); color: var(--primary); }
.sidebar__link.active {
  background: var(--primary-light);
  color: var(--primary);
  font-weight: 600;
}

/* ===== Masonry Gallery (Projects) ===== */
.project-filters {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);
  align-items: center;
}

.filter-select {
  padding: var(--space-sm) var(--space-md);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  background: var(--white);
  color: var(--dark);
  cursor: pointer;
  appearance: none;
  background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1l4 4 4-4' stroke='%23666' stroke-width='1.5' stroke-linecap='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 12px center;
  padding-right: 32px;
  transition: border-color var(--duration-fast);
}
.filter-select:focus { outline: none; border-color: var(--primary); }

.masonry {
  columns: 4;
  column-gap: var(--space-lg);
}

.masonry__item {
  break-inside: avoid;
  margin-bottom: var(--space-lg);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-normal) var(--ease-out);
  cursor: pointer;
}
.masonry__item:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.masonry__image {
  width: 100%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 2rem;
}

.masonry__item:nth-child(odd) .masonry__image { aspect-ratio: 3/4; }
.masonry__item:nth-child(even) .masonry__image { aspect-ratio: 4/3; }
.masonry__item:nth-child(3n) .masonry__image { aspect-ratio: 1/1; }

.masonry__info {
  padding: var(--space-md);
}

.masonry__title {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.masonry__user {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: var(--space-sm);
}

.masonry__stats {
  display: flex;
  gap: var(--space-md);
  font-size: 0.75rem;
  color: var(--gray-400);
}
.masonry__stats span {
  display: flex;
  align-items: center;
  gap: 4px;
}

.masonry__winner {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--yellow);
  color: var(--dark);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
}

.masonry__item { position: relative; }

/* ===== Pricing (Plus page) ===== */
.pricing-hero {
  text-align: center;
  padding: var(--space-4xl) 0 var(--space-2xl);
  background: linear-gradient(135deg, var(--dark) 0%, oklch(22% 0.04 265) 100%);
  color: var(--white);
}

.pricing-hero__subtitle {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: var(--space-md) auto var(--space-xl);
}

.pricing-toggle {
  display: inline-flex;
  background: var(--dark-700);
  border-radius: var(--radius-full);
  padding: 4px;
  gap: 2px;
}

.pricing-toggle__btn {
  padding: var(--space-sm) var(--space-xl);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9375rem;
  transition: all var(--duration-fast);
  position: relative;
}
.pricing-toggle__btn.active {
  background: var(--primary);
  color: var(--white);
}
.pricing-toggle__btn:not(.active) { color: var(--gray-400); }
.pricing-toggle__btn:not(.active):hover { color: var(--white); }

.pricing-toggle__save {
  position: absolute;
  top: -10px;
  right: -10px;
  background: var(--green);
  color: var(--dark);
  font-size: 0.625rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--radius-full);
  white-space: nowrap;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  max-width: 480px;
  margin: var(--space-2xl) auto;
  text-align: left;
  color: var(--dark);
  box-shadow: var(--shadow-xl);
}

.pricing-card__price {
  font-size: 3rem;
  font-weight: 800;
  font-family: var(--font-display);
  line-height: 1;
  margin-bottom: var(--space-xs);
}
.pricing-card__price span { font-size: 1.125rem; font-weight: 500; color: var(--gray-500); }

.pricing-card__billed {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: var(--space-lg);
}

.pricing-card__features {
  margin-bottom: var(--space-xl);
}
.pricing-card__features li {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
}
.pricing-card__features li::before {
  content: "✓";
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card__cta {
  width: 100%;
  text-align: center;
}

.pricing-card__terms {
  font-size: 0.75rem;
  color: var(--gray-400);
  text-align: center;
  margin-top: var(--space-md);
}

/* ===== Benefits Grid ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--space-xl);
}

.benefit-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: all var(--duration-normal);
}
.benefit-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--gray-200);
}

.benefit-card__icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: var(--space-lg);
}

.benefit-card__title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.benefit-card__desc {
  font-size: 0.9375rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 720px; margin: 0 auto; }

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-item__question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-lg) 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  gap: var(--space-md);
  transition: color var(--duration-fast);
}
.faq-item__question:hover { color: var(--primary); }

.faq-item__icon {
  flex-shrink: 0;
  width: 24px; height: 24px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--duration-normal);
  font-size: 0.875rem;
}
