  font-size: 1.5rem;
  font-weight: 800;
  text-align: center;
  margin-bottom: var(--space-2xl);
}
.login-card__logo span { color: var(--primary); }

.login-card__title {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.login-card__subtitle {
  color: var(--gray-500);
  font-size: 0.9375rem;
  margin-bottom: var(--space-xl);
}

.social-btn {
