}
.login-divider::before,
.login-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group {
  margin-bottom: var(--space-md);
}
.form-label {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}
.form-input {
  width: 100%;
  padding: 0.75rem var(--space-md);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
