.form-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-light); }

.password-field {
  position: relative;
}
.password-toggle {
  position: absolute;
  right: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  padding: var(--space-xs);
  cursor: pointer;
}
.password-toggle:hover { color: var(--dark); }

.login-card__forgot {
  display: block;
  text-align: right;
  font-size: 0.8125rem;
  color: var(--primary);
  margin-bottom: var(--space-lg);
  font-weight: 500;
}
.login-card__forgot:hover { text-decoration: underline; }

.login-card__signup {
  text-align: center;
  margin-top: var(--space-xl);
  font-size: 0.875rem;
  color: var(--gray-500);
}
.login-card__signup a {
  color: var(--primary);
  font-weight: 600;
