.pricing-col--recommended::before {
  content: "Best value";
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  white-space: nowrap;
}

.pricing-col__name {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.pricing-col__price {
  font-size: 2.5rem;
  font-weight: 800;
  font-family: var(--font-display);
  margin-bottom: var(--space-xs);
}
.pricing-col__price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-500);
